@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(45.0 16.7% 95.3%);
  --color-foreground: hsl(40.0 12.3% 14.3%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(40.0 12.3% 14.3%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(40.0 12.3% 14.3%);
  --color-primary: hsl(213.6 12.8% 38.2%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(43.6 14.3% 84.9%);
  --color-secondary-foreground: hsl(40.0 12.3% 14.3%);
  --color-muted: hsl(43.6 14.3% 84.9%);
  --color-muted-foreground: hsl(42.0 8.4% 53.3%);
  --color-accent: hsl(41.5 28.9% 91.2%);
  --color-accent-foreground: hsl(36.4 21.6% 30.0%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(42.9 18.9% 85.5%);
  --color-input: hsl(43.3 15.8% 77.6%);
  --color-ring: hsl(213.6 12.8% 38.2%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(45.0 16.7% 95.3%);
  --color-foreground: hsl(40.0 12.3% 14.3%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(40.0 12.3% 14.3%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(40.0 12.3% 14.3%);
  --color-primary: hsl(213.6 12.8% 38.2%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(43.6 14.3% 84.9%);
  --color-secondary-foreground: hsl(40.0 12.3% 14.3%);
  --color-muted: hsl(43.6 14.3% 84.9%);
  --color-muted-foreground: hsl(42.0 8.4% 53.3%);
  --color-accent: hsl(41.5 28.9% 91.2%);
  --color-accent-foreground: hsl(36.4 21.6% 30.0%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(42.9 18.9% 85.5%);
  --color-input: hsl(43.3 15.8% 77.6%);
  --color-ring: hsl(213.6 12.8% 38.2%);
    }

    @variant dark {
  --color-background: hsl(45.0 10.0% 7.8%);
  --color-foreground: hsl(41.5 21.3% 88.0%);
  --color-card: hsl(40.0 10.8% 16.3%);
  --color-card-foreground: hsl(41.5 21.3% 88.0%);
  --color-popover: hsl(40.0 12.0% 9.8%);
  --color-popover-foreground: hsl(41.5 21.3% 88.0%);
  --color-primary: hsl(214.6 12.7% 60.0%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(42.9 10.1% 13.5%);
  --color-secondary-foreground: hsl(41.5 21.3% 88.0%);
  --color-muted: hsl(42.9 10.1% 13.5%);
  --color-muted-foreground: hsl(41.7 9.6% 46.9%);
  --color-accent: hsl(42.0 12.5% 15.7%);
  --color-accent-foreground: hsl(41.3 32.4% 72.7%);
  --color-destructive: hsl(4.6 65.6% 64.7%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(40.0 10.8% 16.3%);
  --color-input: hsl(41.5 11.3% 22.5%);
  --color-ring: hsl(214.0 31.0% 66.5%);
    }
  }
}
